// weapon.js —— 玩家武器系统
// 职责：管理当前武器、射击（射线检测命中敌人/墙）、换弹、武器切换、
//        后坐力、弹道散布、第一人称枪模、弹孔/枪口火光等视觉反馈
// 射击命中判定：从相机发出带散布的射线，与敌人胶囊体（球+圆柱近似）求最近交点，
//                并与地图 AABB 比较——若墙更近则被墙挡住。
// 经典脚本（非 ES Module）：THREE / CONFIG 由前置脚本挂到 window 提供

class WeaponSystem {
  constructor(scene, camera, player, gameMap, enemies, hud, audio) {
    this.scene = scene;
    this.camera = camera;
    this.player = player;
    this.map = gameMap;
    this.enemies = enemies;     // 引用数组（动态）
    this.hud = hud;
    this.audio = audio;

    // 当前武器
    this.currentId = 'usp';
    this.state = this._freshState('usp');

    // 输入
    this.firing = false;        // 鼠标按下持续射击
    this.fireCooldown = 0;
    this.reloadTimer = 0;
    this.switching = false;
    this._bindInput();

    // 第一人称枪模
    this._buildViewModel();
    // 弹道轨迹池（临时线段）
    this._tracers = [];
    this._impacts = [];         // 弹孔
    this._buildImpactPool();
    // 高精度命中：复用单条 Raycaster（三角级精确求交）
    this.raycaster = new THREE.Raycaster();
    this._buildHitPool();
    // 枪口火光
    this._muzzleTimer = 0;
  }

  _freshState(id) {
    const w = CONFIG.weapons[id];
    return {
      id,
      mag: w.magSize,
      reserve: w.reserve,
    };
  }

  _bindInput() {
    this._onMouseDown = (e) => {
      if (e.button === 0) this.firing = true;
    };
    this._onMouseUp = (e) => {
      if (e.button === 0) this.firing = false;
    };
    this._onKeyDown = (e) => {
      if (e.code === 'KeyR') this.startReload();
      if (e.code === 'Digit1') this.switchTo('usp');
      if (e.code === 'Digit2') this.switchTo('ak47');
    };
    // 触屏设备：原生 mouse 事件会由"点击屏幕视角区"合成触发导致误开火，
    // 因此只保留键盘；射击统一走 FIRE 按钮的 setFiring()
    const isTouch = ('ontouchstart' in window) || navigator.maxTouchPoints > 0;
    if (!isTouch) {
      window.addEventListener('mousedown', this._onMouseDown);
      window.addEventListener('mouseup', this._onMouseUp);
    }
    window.addEventListener('keydown', this._onKeyDown);
  }

  // 触屏 FIRE 按钮 / 外部直接控制持续射击状态（自动武器）
  setFiring(v) {
    this.firing = v;
  }

  switchTo(id) {
    if (id === this.currentId) return;
    if (!CONFIG.weapons[id]) return;
    // 保留每种武器的弹匣状态
    if (!this._stash) this._stash = {};
    this._stash[this.currentId] = { ...this.state };
    this.currentId = id;
    this.state = this._stash[id] ? { ...this._stash[id] } : this._freshState(id);
    this.reloadTimer = 0;
    this.fireCooldown = 0.3;    // 切枪延迟
    this.firing = false;
    this.hud.updateWeapon(CONFIG.weapons[id], this.state);
    this.hud.toast(CONFIG.weapons[id].name);
  }

  startReload() {
    const w = CONFIG.weapons[this.currentId];
    if (this.reloadTimer > 0) return;
    if (this.state.mag >= w.magSize) return;
    if (this.state.reserve <= 0) return;
    this.reloadTimer = w.reloadTime;
    this.hud.toast('换弹中…');
  }

  _finishReload() {
    const w = CONFIG.weapons[this.currentId];
    const need = w.magSize - this.state.mag;
    const take = Math.min(need, this.state.reserve);
    this.state.mag += take;
    this.state.reserve -= take;
    this.hud.updateWeapon(w, this.state);
  }

  // 弹药包补给：当前枪与已暂存过的枪都补，各自封顶在初始储备（reserve）
  // 返回 { added, parts }：added=是否有任何补到，parts=['USP +12', ...] 供提示
  addAmmo(refill) {
    const parts = [];
    for (const id of Object.keys(refill)) {
      const w = CONFIG.weapons[id];
      if (!w) continue;
      let before, after;
      if (id === this.currentId) {
        before = this.state.reserve;
        after = Math.min(w.reserve, before + refill[id]);
        if (after > before) {
          this.state.reserve = after;
          this.hud.updateWeapon(w, this.state);
        }
      } else if (this._stash && this._stash[id]) {
        before = this._stash[id].reserve;
        after = Math.min(w.reserve, before + refill[id]);
        if (after > before) this._stash[id].reserve = after;
      } else {
        continue;   // 从未切过的枪储备仍是初始满值，无可补
      }
      if (after > before) parts.push(`${w.name} +${after - before}`);
    }
    return { added: parts.length > 0, parts };
  }

  // ---------- 主更新 ----------
  update(dt) {
    const w = CONFIG.weapons[this.currentId];

    // 换弹
    if (this.reloadTimer > 0) {
      this.reloadTimer -= dt;
      if (this.reloadTimer <= 0) this._finishReload();
    }

    // 射击冷却
    if (this.fireCooldown > 0) this.fireCooldown -= dt;

    // 持续射击（自动武器）
    const wantFire = this.firing && w.type === 'auto';
    const wantFireSemi = this._semiPending;
    if ((wantFire || wantFireSemi) && this.fireCooldown <= 0 && this.reloadTimer <= 0) {
      this._fire();
      this._semiPending = false;
    }

    // 准星扩散与当前散布联动（静止收拢、移动张开，所见即所射）
    const hSpeed = Math.hypot(this.player.velocity.x, this.player.velocity.z);
    const moveFactor = Math.min(1, hSpeed / CONFIG.player.walkSpeed);
    const curSpread = w.spread + w.spreadMove * moveFactor;
    this.hud.setCrosshairSpread(curSpread);

    // 枪模动画
    this._updateViewModel(dt);

    // 弹道/弹孔淡出
    this._updateTracers(dt);

    // 枪口火光衰减（作用于当前武器）
    if (this._muzzleTimer > 0) {
      this._muzzleTimer -= dt;
      const gun = this._viewGuns && this._viewGuns[this.currentId];
      const flash = gun && gun.userData.flash;
      if (flash) flash.material.opacity = Math.max(0, this._muzzleTimer / 0.04);
    }
  }

  // 半自动：鼠标按下触发一次
  triggerSemi() {
    const w = CONFIG.weapons[this.currentId];
    if (w.type === 'semi') this._semiPending = true;
  }

  _fire() {
    const w = CONFIG.weapons[this.currentId];
    if (this.state.mag <= 0) {
      // 空仓
      this.hud.toast('弹匣空了！按 R 换弹');
      this.fireCooldown = 0.2;
      this.firing = false;
      if (w.autoReload) this.startReload();
      return;
    }
    this.state.mag--;
    this.fireCooldown = w.fireRate;
    this.hud.updateWeapon(w, this.state);
    this.hud.crosshairFire();

    // 计算弹道方向（带散布）
    const ray = this.player.getAimRay();
    // 移动时散布更大
    const hSpeed = Math.hypot(this.player.velocity.x, this.player.velocity.z);
    const moveFactor = Math.min(1, hSpeed / CONFIG.player.walkSpeed);
    const spread = w.spread + w.spreadMove * moveFactor;
    const dir = ray.direction.clone();
    // 在"屏幕平面"内做圆盘均匀采样（用相机右/上向量做基），
    // 保证弹孔分布始终落在准星扩散范围内，且朝向任意角度都不会畸变
    if (spread > 0) {
      const right = new THREE.Vector3(1, 0, 0).applyQuaternion(this.camera.quaternion);
      const up = new THREE.Vector3(0, 1, 0).applyQuaternion(this.camera.quaternion);
      const ang = Math.random() * Math.PI * 2;
      const rad = spread * Math.sqrt(Math.random());
      dir.addScaledVector(right, Math.cos(ang) * rad)
         .addScaledVector(up, Math.sin(ang) * rad)
         .normalize();
    }

    const origin = ray.origin.clone();

    // 后坐力
    this.player.applyRecoil(w.recoil);

    // ---- 高精度命中：Three.js Raycaster 对敌人真实网格做三角级求交 ----
    const hit = this._hitscan(origin, dir, w.range);
    // 墙遮挡：地图 AABB 精确求交（含命中面法线，用于弹孔贴墙）
    const wall = this.map.raycastDetailed(origin, dir, w.range);

    // 视觉：弹道轨迹终点（取最近命中点：敌人 / 墙 / 最大射程）
    let endT = w.range;
    if (hit && hit.t < endT) endT = hit.t;
    if (wall.t < endT) endT = wall.t;
    const endPoint = origin.clone().addScaledVector(dir, endT);
    this._spawnTracer(origin, endPoint);
    this._spawnMuzzleFlash();

    // 命中处理
    if (hit && hit.t < wall.t) {
      const dmg = this._damageForPart(w, hit.part);
      const killed = hit.enemy.takeDamage(dmg, hit.part);
      this.hud.hitMarker(hit.part === 'head');
      this._spawnHitSpark(hit.point, hit.normal, hit.part);
      if (killed) this.hud.killFeed(hit.enemy.name);
    } else if (wall.t < w.range) {
      // 击中墙体，按墙面法线贴弹孔（精确贴合墙面）
      this._spawnImpact(endPoint, wall.normal || dir.clone().negate());
    }

    // 音效
    if (this.audio) this.audio.shot(this.currentId);
  }

  // 高精度命中：对全部存活敌人网格做三角级射线求交，返回最近命中
  // { enemy, part, t, point, normal } 或 null
  _hitscan(origin, dir, range) {
    const targets = [];
    for (const en of this.enemies) {
      if (!en.alive) continue;
      // 敌人本帧刚移动过，强制刷新世界矩阵，保证命中与渲染位置一致
      en.mesh.updateMatrixWorld(true);
      for (const m of en.hitMeshes) targets.push(m);
    }
    if (targets.length === 0) return null;

    this.raycaster.set(origin, dir);
    this.raycaster.near = 0.001;
    this.raycaster.far = range;
    const hits = this.raycaster.intersectObjects(targets, false);
    if (hits.length === 0) return null;

    // intersectObjects 已按距离升序排序，取最近者
    const h = hits[0];
    const obj = h.object;
    // 面法线从局部空间变换到世界空间（用于精确着弹点特效）
    const normal = h.face
      ? h.face.normal.clone().transformDirection(obj.matrixWorld).normalize()
      : dir.clone().negate();
    return {
      enemy: obj.userData.enemy,
      part: obj.userData.part || 'torso',
      t: h.distance,
      point: h.point.clone(),
      normal,
    };
  }

  // 部位 → 伤害倍率（head/torso/arm/leg/gun）
  _damageForPart(w, part) {
    switch (part) {
      case 'head': return w.damage * w.headMult;
      case 'leg':  return w.damage * w.legMult;
      case 'arm':  return w.damage * (w.armMult ?? 1);
      case 'gun':  return w.damage * (w.gunMult ?? 0.5);
      default:     return w.damage;   // torso / body
    }
  }

  // 着弹点特效池（命中敌人时在精确命中点闪出血花/爆头火花）
  _buildHitPool() {
    this._hitPool = [];
    const mat = new THREE.SpriteMaterial({
      color: 0xff2a2a, transparent: true, opacity: 0.95,
    });
    for (let i = 0; i < 30; i++) {
      const s = new THREE.Sprite(mat.clone());
      s.scale.setScalar(0.14);
      s.visible = false;
      this.scene.add(s);
      this._hitPool.push(s);
    }
    this._hitSparks = [];
  }

  _spawnHitSpark(point, normal, part) {
    let s = this._hitPool.pop();
    if (!s) return;
    s.position.copy(point).addScaledVector(normal, 0.02);
    s.material.color.setHex(part === 'head' ? 0xffe14d : 0xff2a2a);
    s.scale.setScalar(part === 'head' ? 0.22 : 0.14);
    s.visible = true;
    s.material.opacity = 0.95;
    s.userData.life = 0.12;
    this.scene.add(s);
    this._hitSparks.push(s);
  }

  // ---------- 视觉：第一人称枪模（高精度程序化贴图版） ----------
  _buildViewModel() {
    this._viewGroup = new THREE.Group();
    this.camera.add(this._viewGroup);
    this.scene.add(this.camera);   // 确保 camera 加入场景，枪模跟随

    // 贴图：先用程序化贴图兜底，再异步加载联网下载的真实贴图替换（避免加载瞬间黑帧）
    const texMetal = this._makeMetalTexture();
    const texWood = this._makeWoodTexture();
    const texGrip = this._makeGripTexture();

    // 共享材质（金属/木纹用真实贴图替换，防滑纹保持程序化）
    const metalMat = new THREE.MeshStandardMaterial({ map: texMetal, roughness: 0.45, metalness: 0.75 });
    const metalDarkMat = new THREE.MeshStandardMaterial({ map: texMetal, color: 0xbfc0c6, roughness: 0.5, metalness: 0.75 });
    const woodMat = new THREE.MeshStandardMaterial({ map: texWood, roughness: 0.7, metalness: 0.02 });
    const gripMat = new THREE.MeshStandardMaterial({ map: texGrip, roughness: 0.8, metalness: 0.15 });

    // 联网贴图加载完成后替换（无则保持程序化兜底）
    this._applyTex(window.TEX && window.TEX.metal, [metalMat, metalDarkMat]);
    this._applyTex(window.TEX && window.TEX.wood, [woodMat]);

    // 两把枪各自独立的高精度模型，切换时显隐
    this._viewGuns = {
      usp: this._buildUSP(metalMat, metalDarkMat, gripMat),
      ak47: this._buildAK(metalMat, woodMat, gripMat),
    };
    this._viewGroup.add(this._viewGuns.usp);
    this._viewGroup.add(this._viewGuns.ak47);

    // 当前枪模姿态
    this._viewRecoil = 0;
  }

  // 真实贴图加载完成后替换材质贴图（离线 base64，无 CORS 问题）
  _applyTex(url, mats) {
    if (!url) return;
    new THREE.TextureLoader().load(url, (tex) => {
      tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
      if ('SRGBColorSpace' in THREE) tex.colorSpace = THREE.SRGBColorSpace;
      for (const m of mats) { m.map = tex; m.needsUpdate = true; }
    });
  }

  // ---- 程序化贴图 ----

  // 拉丝枪金属（深灰 + 竖向细纹 + 顶部高光 + 面板分割线）
  _makeMetalTexture() {
    const c = document.createElement('canvas');
    c.width = 256; c.height = 256;
    const g = c.getContext('2d');
    g.fillStyle = '#2b2d33';
    g.fillRect(0, 0, 256, 256);
    for (let i = 0; i < 256; i++) {
      const v = 34 + Math.random() * 40;
      g.fillStyle = `rgba(${v},${v + 2},${v + 6},0.06)`;
      g.fillRect(i, 0, 1, 256);
    }
    const grad = g.createLinearGradient(0, 0, 0, 256);
    grad.addColorStop(0, 'rgba(255,255,255,0.12)');
    grad.addColorStop(0.45, 'rgba(255,255,255,0)');
    grad.addColorStop(1, 'rgba(0,0,0,0.22)');
    g.fillStyle = grad;
    g.fillRect(0, 0, 256, 256);
    g.strokeStyle = 'rgba(0,0,0,0.45)';
    g.lineWidth = 2;
    for (let y = 64; y < 256; y += 70) {
      g.beginPath(); g.moveTo(0, y); g.lineTo(256, y); g.stroke();
    }
    return new THREE.CanvasTexture(c);
  }

  // 木纹（棕色 + 横向波浪纹）
  _makeWoodTexture() {
    const c = document.createElement('canvas');
    c.width = 256; c.height = 256;
    const g = c.getContext('2d');
    g.fillStyle = '#6a4a2a';
    g.fillRect(0, 0, 256, 256);
    for (let y = 0; y < 256; y += 7) {
      g.strokeStyle = `rgba(${36 + Math.random() * 28},${22 + Math.random() * 18},${10},${0.25 + Math.random() * 0.3})`;
      g.lineWidth = 1 + Math.random() * 2;
      g.beginPath();
      for (let x = 0; x <= 256; x += 12) {
        const yy = y + Math.sin(x * 0.06 + y * 0.3) * 3;
        if (x === 0) g.moveTo(x, yy); else g.lineTo(x, yy);
      }
      g.stroke();
    }
    return new THREE.CanvasTexture(c);
  }

  // 防滑纹（深黑 + 密集点纹）
  _makeGripTexture() {
    const c = document.createElement('canvas');
    c.width = 256; c.height = 256;
    const g = c.getContext('2d');
    g.fillStyle = '#17171b';
    g.fillRect(0, 0, 256, 256);
    for (let y = 5; y < 256; y += 11) {
      for (let x = 5; x < 256; x += 11) {
        g.fillStyle = `rgba(${58 + Math.random() * 26},${58 + Math.random() * 26},${64 + Math.random() * 26},0.55)`;
        g.beginPath(); g.arc(x, y, 3, 0, Math.PI * 2); g.fill();
      }
    }
    return new THREE.CanvasTexture(c);
  }

  // 枪口火光网格（挂到每把枪的 userData.flash）
  _makeMuzzleFlashMesh(x, y, z) {
    const mat = new THREE.MeshBasicMaterial({
      color: 0xffcc44, transparent: true, opacity: 0, depthTest: false,
    });
    const flash = new THREE.Mesh(new THREE.SphereGeometry(0.06, 8, 8), mat);
    flash.position.set(x, y, z);
    return flash;
  }

  // USP 手枪：套筒 + 防滑槽 + 枪身 + 扳机护圈 + 照门/准星 + 击锤 + 握把
  _buildUSP(metalMat, darkMat, gripMat) {
    const g = new THREE.Group();
    const X = 0.22;

    const slide = new THREE.Mesh(new THREE.BoxGeometry(0.05, 0.055, 0.24), metalMat);
    slide.position.set(X, -0.145, -0.52);
    g.add(slide);

    for (let i = 0; i < 4; i++) {
      const serr = new THREE.Mesh(new THREE.BoxGeometry(0.052, 0.006, 0.012), darkMat);
      serr.position.set(X, -0.145, -0.44 - i * 0.016);
      g.add(serr);
    }

    const frame = new THREE.Mesh(new THREE.BoxGeometry(0.048, 0.05, 0.17), darkMat);
    frame.position.set(X, -0.205, -0.48);
    g.add(frame);

    const guard = new THREE.Mesh(new THREE.BoxGeometry(0.02, 0.012, 0.07), darkMat);
    guard.position.set(X, -0.24, -0.48);
    g.add(guard);

    const grip = new THREE.Mesh(new THREE.BoxGeometry(0.046, 0.15, 0.08), gripMat);
    grip.position.set(X, -0.31, -0.42);
    grip.rotation.x = -0.22;
    g.add(grip);

    const rearSight = new THREE.Mesh(new THREE.BoxGeometry(0.014, 0.03, 0.014), darkMat);
    rearSight.position.set(X, -0.112, -0.44);
    g.add(rearSight);

    const frontSight = new THREE.Mesh(new THREE.BoxGeometry(0.012, 0.022, 0.012), darkMat);
    frontSight.position.set(X, -0.112, -0.62);
    g.add(frontSight);

    const hammer = new THREE.Mesh(new THREE.BoxGeometry(0.03, 0.025, 0.02), darkMat);
    hammer.position.set(X, -0.13, -0.38);
    g.add(hammer);

    const muzzle = new THREE.Mesh(new THREE.CylinderGeometry(0.016, 0.016, 0.02, 12), darkMat);
    muzzle.rotation.x = Math.PI / 2;
    muzzle.position.set(X, -0.145, -0.645);
    g.add(muzzle);

    const flash = this._makeMuzzleFlashMesh(X, -0.145, -0.66);
    g.add(flash);
    g.userData.flash = flash;
    return g;
  }

  // AK-47：机匣 + 枪管 + 导气管 + 准星 + 木护木 + 木枪托 + 弧形弹匣 + 握把
  _buildAK(metalMat, woodMat, gripMat) {
    const g = new THREE.Group();
    const X = 0.22;

    const receiver = new THREE.Mesh(new THREE.BoxGeometry(0.05, 0.07, 0.3), metalMat);
    receiver.position.set(X, -0.185, -0.55);
    g.add(receiver);

    const barrel = new THREE.Mesh(new THREE.CylinderGeometry(0.02, 0.02, 0.36, 14), metalMat);
    barrel.rotation.x = Math.PI / 2;
    barrel.position.set(X, -0.16, -0.82);
    g.add(barrel);

    const gas = new THREE.Mesh(new THREE.CylinderGeometry(0.013, 0.013, 0.3, 12), metalMat);
    gas.rotation.x = Math.PI / 2;
    gas.position.set(X, -0.115, -0.76);
    g.add(gas);

    const frontPost = new THREE.Mesh(new THREE.BoxGeometry(0.012, 0.05, 0.012), metalMat);
    frontPost.position.set(X, -0.115, -0.96);
    g.add(frontPost);

    const rearSight = new THREE.Mesh(new THREE.BoxGeometry(0.014, 0.03, 0.014), metalMat);
    rearSight.position.set(X, -0.14, -0.42);
    g.add(rearSight);

    const handguard = new THREE.Mesh(new THREE.BoxGeometry(0.058, 0.06, 0.16), woodMat);
    handguard.position.set(X, -0.17, -0.68);
    g.add(handguard);

    const stock = new THREE.Mesh(new THREE.BoxGeometry(0.05, 0.06, 0.2), woodMat);
    stock.position.set(X, -0.19, -0.36);
    g.add(stock);

    const mag = new THREE.Mesh(new THREE.BoxGeometry(0.04, 0.17, 0.09), metalMat);
    mag.position.set(X, -0.32, -0.5);
    mag.rotation.x = 0.35;
    g.add(mag);

    const grip = new THREE.Mesh(new THREE.BoxGeometry(0.046, 0.12, 0.06), gripMat);
    grip.position.set(X, -0.28, -0.44);
    grip.rotation.x = -0.25;
    g.add(grip);

    const flash = this._makeMuzzleFlashMesh(X, -0.16, -1.0);
    g.add(flash);
    g.userData.flash = flash;
    return g;
  }

  _spawnMuzzleFlash() {
    const gun = this._viewGuns && this._viewGuns[this.currentId];
    const flash = gun && gun.userData.flash;
    if (flash) {
      flash.material.opacity = 1;
      flash.scale.setScalar(0.8 + Math.random() * 0.6);
      flash.rotation.z = Math.random() * Math.PI;
    }
    this._muzzleTimer = 0.04;
    // 枪模后坐位移
    this._viewRecoil = 1;
  }

  _updateViewModel(dt) {
    const w = CONFIG.weapons[this.currentId];
    // 切换武器显隐（两把枪各自独立高精度枪模）
    if (this._viewGuns) {
      this._viewGuns.usp.visible = (this.currentId === 'usp');
      this._viewGuns.ak47.visible = (this.currentId === 'ak47');
    }

    // ---- 后坐力回弹：枪口向上挑（rotation.x 正值 = 前方枪口抬起）+ 轻微后缩 ----
    this._viewRecoil = Math.max(0, this._viewRecoil - dt * 8);
    const kick = this._viewRecoil;
    // 上挑角度随武器后坐力参数放大（峰值 ≈ 7°~9°，视觉明显上跳）
    const recoilPitch = kick * (0.09 + w.recoil.x * 3.2);
    const recoilPush = kick * 0.05;      // 轻微后缩

    // 走路晃动
    const bob = Math.sin(this.player.viewBob * 2) * 0.01;
    this._viewGroup.position.x = bob * 0.5;
    this._viewGroup.position.y = -Math.abs(bob) * 0.5;
    this._viewGroup.position.z = recoilPush;

    // 换弹时枪下倾（与后坐上挑叠加，不再互相覆盖）
    let dip = 0;
    if (this.reloadTimer > 0) {
      const t = 1 - this.reloadTimer / w.reloadTime;
      dip = Math.sin(t * Math.PI) * 0.4;
    }
    this._viewGroup.rotation.x = recoilPitch + dip;
  }

  // ---------- 弹道与弹孔 ----------
  _spawnTracer(from, to) {
    // 池化复用：避免每发子弹 new Geometry/Line（高频分配触发 GC 卡顿）
    let line = this._tracerPool && this._tracerPool.pop();
    if (!line) {
      const geo = new THREE.BufferGeometry().setFromPoints([from, to]);
      const mat = new THREE.LineBasicMaterial({
        color: 0xffee88, transparent: true, opacity: 0.8,
      });
      line = new THREE.Line(geo, mat);
      this._tracerPool = this._tracerPool || [];
    } else {
      line.geometry.setFromPoints([from, to]);
    }
    line.userData.life = 0.06;
    line.material.opacity = 0.8;
    line.visible = true;
    this.scene.add(line);
    this._tracers.push(line);
  }

  _updateTracers(dt) {
    for (let i = this._tracers.length - 1; i >= 0; i--) {
      const t = this._tracers[i];
      t.userData.life -= dt;
      t.material.opacity = Math.max(0, t.userData.life / 0.06) * 0.8;
      if (t.userData.life <= 0) {
        this.scene.remove(t);
        t.visible = false;
        this._tracerPool.push(t);   // 归还池中复用，不再 dispose
        this._tracers.splice(i, 1);
      }
    }
    for (let i = this._impacts.length - 1; i >= 0; i--) {
      const m = this._impacts[i];
      m.userData.life -= dt;
      if (m.userData.life <= 0) {
        this.scene.remove(m);
        this._impactPool.push(m);
        this._impacts.splice(i, 1);
      }
    }
    for (let i = this._hitSparks.length - 1; i >= 0; i--) {
      const s = this._hitSparks[i];
      s.userData.life -= dt;
      s.material.opacity = Math.max(0, s.userData.life / 0.12);
      if (s.userData.life <= 0) {
        this.scene.remove(s);
        s.visible = false;
        this._hitPool.push(s);
        this._hitSparks.splice(i, 1);
      }
    }
  }

  _buildImpactPool() {
    this._impactPool = [];
    const geo = new THREE.CircleGeometry(0.06, 8);
    const mat = new THREE.MeshBasicMaterial({
      color: 0x111111, transparent: true, opacity: 0.9, side: THREE.DoubleSide,
    });
    for (let i = 0; i < 30; i++) {
      const m = new THREE.Mesh(geo, mat.clone());
      m.visible = false;
      this.scene.add(m);
      this._impactPool.push(m);
    }
  }

  _spawnImpact(point, normal) {
    let m = this._impactPool.pop();
    if (!m) return;
    // 沿墙面外法线微偏移避免 Z-fighting；面朝向法线，精确贴合墙面
    m.position.copy(point).addScaledVector(normal, 0.01);
    m.lookAt(point.clone().add(normal));
    m.visible = true;
    m.material.opacity = 0.9;
    m.userData.life = 6;
    this.scene.add(m);
    this._impacts.push(m);
  }

  reset() {
    this.currentId = 'usp';
    this.state = this._freshState('usp');
    this._stash = {};
    this.firing = false;
    this.reloadTimer = 0;
    this.fireCooldown = 0;
    this.hud.updateWeapon(CONFIG.weapons.usp, this.state);
  }

  dispose() {
    window.removeEventListener('mousedown', this._onMouseDown);
    window.removeEventListener('mouseup', this._onMouseUp);
    window.removeEventListener('keydown', this._onKeyDown);
  }
}

